custom.expression:
let res = 280.0 / pixel_size;
let q = (floor(p * res) + 0.5) / res;
let tick = t * round(drive_speed * 3300.0) / 3600.0;
let sway = sin(tick * 0.6283185);
let x = q.x + 0.018 * sway;
let h = q.y + 0.105;
let sky = mix(mix(c3,c4,0.45),c2,smoothstep(0.0,0.58,h));
let s = vec2<f32>(x + 0.27,h - 0.19);
let bands = smoothstep(0.18,0.39,fract(s.y * 49.0));
let sun = fill(length(s) - 0.142) * mix(bands,1.0,smoothstep(-0.073,0.025,s.y));
let far = fill(h - 0.025 - 0.16 * noise(vec2<f32>(x * 2.8,7.0)));
let ridge = 0.12 * noise(vec2<f32>(x * 5.7,2.0)) + 0.017 * hash(vec2<f32>(floor(x * 111.0),9.0));
let near = fill(h - ridge);
let d = max(-h,0.0);
let land = mix(c2 * 0.72,c5 * 0.48,smoothstep(0.0,0.39,d));
let hills = mix(mix(mix(sky,c4,sun),c2 * 0.92,far),land,near);
let bend = 0.02 - 0.80 * d * d + 0.04 * d * sway;
let u = abs(x - bend) / (d + 0.007);
let z = 0.42 / (d + 0.048) + tick;
let f = fract(z);
let dash = smoothstep(0.13,0.19,f) * (1.0 - smoothstep(0.52,0.58,f));
let fog = smoothstep(0.012,0.069,d);
let road = (1.0 - smoothstep(1.24,1.29,u)) * smoothstep(0.0,0.016,d);
let mid = (1.0 - smoothstep(0.022,0.049,u)) * dash * fog;
let edge = 1.0 - smoothstep(0.017,0.040,abs(u - 1.13));
let curb = (1.0 - smoothstep(0.042,0.078,abs(u - 1.23))) * fog;
let stone = mix(c2 * 0.89,mix(c1,c2,0.44),smoothstep(0.0,0.40,d));
let lanes = mix(mix(mix(stone,c4,mid),c5,edge * fog),mix(c3,c4,dash),curb * 0.8);
let scene = mix(hills,lanes,road);
let a = vec2<f32>(x - 0.38,q.y - 0.076);
let board = sd_box(a,vec2<f32>(0.143,0.052));
let post = fill(sd_box(a + vec2<f32>(0.0,0.121),vec2<f32>(0.006,0.084)));
let g = vec2<f32>(a.x + 0.125,0.036 - a.y) * 156.0;
let j = floor(g.x * 0.25);
let k = floor(g.x) - j * 4.0;
let row = floor(g.y);
let top = select(0.0,29847.0,j==0.0)+select(0.0,448.0,j==1.0)+select(0.0,29330.0,j==2.0)+select(0.0,31183.0,j==3.0)+select(0.0,24557.0,j==5.0)+select(0.0,31599.0,j==6.0)+select(0.0,27565.0,j==7.0)+select(0.0,29842.0,j==8.0)+select(0.0,23533.0,j==9.0);
let low = select(0.0,23469.0,j==1.0)+select(0.0,31143.0,j==2.0)+select(0.0,24557.0,j==3.0)+select(0.0,29842.0,j==4.0)+select(0.0,23407.0,j==5.0)+select(0.0,31015.0,j==6.0)+select(0.0,23469.0,j==7.0)+select(0.0,23186.0,j==8.0);
let r = select(row,row - 7.0,row >= 7.0);
let bits = select(top,low,row >= 7.0);
let ink = step(0.5,fract(0.5 * floor(bits / pow(2.0,clamp(14.0 - 3.0*r - k,0.0,14.0))))) * step(0.0,r) * (1.0-step(5.0,r)) * (1.0-step(3.0,k));
let signface = mix(mix(c1,c5,0.25),c5,max(ink,stroke(board + 0.006,0.0017)));
let frame = mix(mix(scene,c2 * 0.77,post),signface,fill(board));
return mix(bg,frame * (1.0 - scanlines * (0.5 + 0.5 * cos(p.y * 850.0))),strength);
